#!/bin/bash
set -eo pipefail
set -o noclobber
umask 077
test "$(id -un)" = sunyiq
task_parent='/data1/home/sunyiq/china_radiation_16_hpc_20261012_001'
test ! -e "$task_parent"
mkdir "$task_parent"
task_root="$task_parent/preflight_v1"
mkdir "$task_root" "$task_root/logs"
printf '%s' '' | base64 -d > "$task_root/preflight.py"
printf '%s' '' | base64 -d > "$task_root/preflight.sbatch"
printf '%s  %s
' '0ea7a4414533c1570aa5edb8903252ffe8b6202b85e9f9a7d7993d4e39096386' "$task_root/preflight.py" | sha256sum -c
printf '%s  %s
' '26d8922eae6bbe539196f03ce2b5bf63be9a69d371deb1c48047cc935376e638' "$task_root/preflight.sbatch" | sha256sum -c
printf 'OWN_PREFLIGHT_SUBMISSION_ONCE
' > "$task_root/SUBMISSION_STARTED.txt"
set +e
task_submission=$(sbatch "$task_root/preflight.sbatch" 2>&1)
task_exit=$?
set -e
printf '%s
' "$task_submission" > "$task_root/SUBMISSION_OUTPUT.txt"
printf '%s
OWN_PREFLIGHT_SUBMIT_EXIT=%s
' "$task_submission" "$task_exit"
test "$task_exit" -eq 0
if [[ "$task_submission" =~ ^Submitted\ batch\ job\ ([0-9]+)$ ]]; then
    task_job="${BASH_REMATCH[1]}"
else
    printf 'OWN_PREFLIGHT_SUBMISSION_UNCERTAIN_NO_RETRY
'
    exit 1
fi
printf '%s
' "$task_job" > "$task_root/OWN_PREFLIGHT_JOB_ID.txt"
printf 'OWN_PREFLIGHT_JOB_ID=%s
' "$task_job"
set +e
timeout 12s squeue -j "$task_job" -h -o '%i|%j|%T|%R'
task_query_exit=$?
set -e
printf 'OWN_PREFLIGHT_SQUEUE_EXIT=%s\n' "$task_query_exit"
printf 'OWN_PREFLIGHT_DEPLOY_DONE
'
